/* AKTY metrykalne. Nowy akt = nowy obiekt w DRZEWO.acts. Pola:
     id     "u" chrzest/urodzenie, "s" ślub, "z" zgon + rok + "-" + numer aktu, np. "z1861-91" (kotwica akty.html#z1861-91)
     osoby  [id z DRZEWO.people] — pierwsza osoba to bohater aktu; pozostali to rodzice, świadkowie, zgłaszający
     y rok;  k "chrzest" | "ślub" | "zgon";  no numer aktu;  g pokolenie linii prostej, którego dotyczy (1–7)
     t      tytuł;  q  cytat z aktu (pisownia oryginalna);  tr  „po współczesnemu”
     scan   hash skanu z photos.szukajwarchiwach.gov.pl (link: …/<hash>_max)
     unit   numer jednostki w szukajwarchiwach (gdy nie ma skanu konkretnej strony)
     fs     link do FamilySearch;  idx  true = znany z indeksu Geneteki;  url  link do skanu (np. metryki.genealodzy.pl)
     parish parafia, gdy inna niż Chorzele (np. "Myszyniec")
     r      stan odczytu: "1 odczyt" | "2 odczyty" | "sprawdzone" (przeczytane osobiście przez Adriana) */
window.DRZEWO = window.DRZEWO || {};

DRZEWO.gloss = [
    ["niegdy", "zmarły, nieżyjący („syn niegdy Kacpra” = syn zmarłego Kacpra)"],
    ["młodzian", "kawaler"],
    ["wyrobnik, wyrobnica", "najemny robotnik bez własnej ziemi"],
    ["z Chudzików", "z domu Chudzik (nazwisko panieńskie)"],
    ["podwójna data, np. 16/28 IV", "kalendarz juliański (rosyjski) / gregoriański"],
    ["„1 odczyt”", "akt przeczytany raz; „sprawdzone” = przeczytany ponownie przez Adriana / drugi raz"],
];

DRZEWO.acts = [
    { id: "s1750", osoby: ["pawel", "jadwiga"], y: 1750, k: "ślub", no: "—", g: 7, t: "Paweł Jentosiak × Jadwiga", fs: "https://www.familysearch.org/ark:/61903/3:1:3Q9M-CSXV-D3L7-2?cat=317312&view=explore&lang=en&groupId=M999-NYD", r: "1 odczyt",
      q: "Matrimonium Contractum inter honestos Paulum Jentosiak de Villa Połonie et Hedvigim Virginem Benedixi in Facie Ecclesiae",
      tr: "8 lutego 1750 r. pobłogosławiłem w kościele małżeństwo zawarte między uczciwymi Pawłem Jentosiakiem ze wsi Połoń a Jadwigą, panną, po zwykłych zapowiedziach. Świadkowie: Paweł Chudzik, Wojciech P…sik ze wsi Pogorzel i inni z ludu." },
    { id: "u1720-4", osoby: ["pawel", "jakub-j", "marianna-j"], y: 1720, k: "chrzest", no: 4, g: 7, t: "Paweł, syn Jakuba i Marianny", fs: "https://www.familysearch.org/ark:/61903/3:1:3Q9M-CSXV-D3LF-P?cat=317312&view=explore&lang=en&groupId=M999-NY8", r: "1 odczyt",
      q: "4 Połomia Eod[em] die quo supra. Suprascriptus baptizavi filium N[omi]ne Paulum honestorum Jacobi Jentosiak et Mariannae legitimorum Conjugum. Levantibus Nobili Joanne Czaplicki[?] et Ursula[?].",
      tr: "25 stycznia 1720 r., Połoń (w księdze „Połomia”). Ochrzciłem syna imieniem Paweł, uczciwych Jakuba Jentosiaka i Marianny, prawowitych małżonków. Chrzestni: szlachetny Jan Czaplicki [?] i Urszula. Skorowidz urodzeń (odczytany dwa razy) zapisał: „Paweł Jutosiak | Jakuba i Marianny | 4”." },
    { id: "u1759-sk", osoby: ["kacper", "agnieszka-p", "pawel", "jadwiga"], y: 1759, k: "chrzest", no: "k. 207", g: 6, t: "Kacper i Agnieszka, bliźnięta (skorowidz)", fs: "https://www.familysearch.org/ark:/61903/3:1:3Q9M-CSXV-KS3R-5", r: "1 odczyt",
      q: "Kacper i Agnieszka Jentosiaki | Pawła i Jadwigi | 207",
      tr: "Skorowidz urodzonych parafii Chorzele, litera K, rok 1759: Kacper i Agnieszka Jentosiakowie, dzieci Pawła i Jadwigi, karta 207. To XIX-wieczny indeks, nie akt — oryginalnej księgi chrztów z tych lat nie ma na FamilySearch, więc nie znamy dnia chrztu ani chrzestnych." },
    { id: "s1786-28", osoby: ["kacper", "helena", "pawel", "jadwiga"], y: 1786, k: "ślub", no: 28, g: 6, t: "Kacper Jentosiak × Helena", fs: "https://www.familysearch.org/ark:/61903/3:1:3Q9M-CSXV-V9LQ-1", r: "1 odczyt",
      q: "HH. Gasparus Pauli et Hedvigis Jętosiak [?] filius, H. Helena HH. olim [?] Mariannae Żodorowa [?] filia de villa Połon Parochiani Chorzel … Calibes",
      tr: "22 listopada 1786 r., Chorzele. Uczciwi Kacper, syn Pawła i Jadwigi Jętosiaków, i Helena, córka zmarłej [?] Marianny „Żodorowej” [?], oboje z Połoni, po trzech zapowiedziach. Świadkowie: Michał Bączek i Szczepan Fatkasiuk [?]. Oboje stanu wolnego. To ten akt dowodzi, że Kacper był synem Pawła i Jadwigi. Skorowidz zapisał pannę młodą jako „Helenę Tudor”." },
    { id: "z1795-pawel", osoby: ["pawel"], y: 1795, k: "zgon", no: "—", g: 7, t: "Paweł Jętosiak", fs: "https://www.familysearch.org/ark:/61903/3:1:3Q9M-CSXV-V9G6-K?cat=317312&view=explore&lang=en&groupId=M9XB-XQM", r: "1 odczyt",
      q: "[Die] 5 Janu: obiit H. Paulus Jętosiak[?] ano 70 munitus S[acramen]tis sepultus in Ecclesia",
      tr: "5 stycznia 1795 r., Połoń. Zmarł uczciwy Paweł Jętosiak, lat 70, zaopatrzony sakramentami, pochowany w kościele. Pierwsza litera nazwiska jest kaligraficzna (J albo Ł)." },
    { id: "u1799-23", osoby: ["walenty", "kacper", "helena"], y: 1799, k: "chrzest", no: 23, g: 5, t: "Walenty, syn Kacpra", fs: "https://www.familysearch.org/ark:/61903/3:1:3Q9M-CSXV-V9K8-W?cat=317312", r: "1 odczyt",
      q: "Die 15 Febr. Anno 1799 … Valentinum filium natum 13. hora 7 vesp. Honestt. Gasparis Jętosiak et Helenae de Dodorow [?] Conjug. Legitt. Patrini fuere Honesti Josephus Kutta et Hedvigis uxor ejus.",
      tr: "15 lutego 1799 r. ochrzczono Walentego, urodzonego 13 lutego o 7 wieczorem, syna uczciwych Kacpra Jętosiaka i Heleny z Dodorów [?], prawowitych małżonków. Chrzestni: Józef Kutta i jego żona Jadwiga. Chrzcił ks. Kazimierz Black." },
    { id: "s1822-fs", osoby: ["walenty", "marianna-ch"], y: 1822, k: "ślub", no: "—", g: 5, t: "Walenty Jentosiak × Marianna Chudzikówna", fs: "https://www.familysearch.org/ark:/61903/3:1:3Q9M-CSXV-V95B-M", r: "1 odczyt",
      q: "Aº 22. die 17. Februar: … inter HH: Valentino Jentosiak Juvenem, Aº 23. et Mariannam Chudzikówna Virginem Aº 16. Parochianos Chorzellenses … Praesentibus Testibus HH: Adamo Jentosiak, et Rocho Bzech[?]",
      tr: "17 lutego 1822 r., Chorzele. Ślub Walentego Jentosiaka, kawalera, 23 lata, z Marianną Chudzikówną, panną, 16 lat. Świadkowie: Adam Jentosiak i Roch Bzech [?]. Rodziców nie podano — księga do 1824 r. ma krótką formułę." },
    { id: "u1806-stan", osoby: ["stanislaw-k", "kacper", "helena"], y: 1806, k: "chrzest", no: "—", g: 6, t: "Stanisław, syn Kacpra", fs: "https://www.familysearch.org/ark:/61903/3:1:3Q9M-CSXV-V9PP-1?cat=317312&view=explore&lang=en&groupId=M9XB-X35", r: "1 odczyt",
      q: "Honestis Gasparo Jentosiak et Helenae Wysocka Legitimis Conjugibus Agricolis Die 10 Aprilis Anno 1806 natus est Filius, qui a me ut supra Die 11 ejusdem baptisatus est, Cui nomen imposui Stanislaus.",
      tr: "Uczciwym Kacprowi Jentosiakowi i Helenie „Wysockiej”, prawowitym małżonkom, rolnikom, 10 kwietnia 1806 r. urodził się syn, ochrzczony 11 kwietnia; nadano mu imię Stanisław. Chrzestni: sławetny Jakub Czerwiński, mieszczanin chorzelski i organista, oraz Marianna Bańkówna, panna z Połoni. Wiek przy ślubie w 1825 r. (19 lat) się zgadza." },
    { id: "z1805-36", osoby: ["jan-kanty", "kacper", "helena"], y: 1805, k: "zgon", no: 36, g: 6, t: "Jan Kanty, syn Kacpra", fs: "https://www.familysearch.org/ark:/61903/3:1:3Q9M-CSXV-V9RW-1?cat=317312&view=explore&lang=en&groupId=M9XB-X3Y", r: "1 odczyt",
      q: "Obiit Infans nomine Joannes Cantius HH. Gasparis, et Helenae Wysocka[?] Jentosiaków, in eadem villa Agricolarum filius, an: 1 et ½ | ex morbo ignoto",
      tr: "5 lutego 1805 r., o 11 wieczorem, zmarło dziecko Jan Kanty, syn uczciwych Kacpra i Heleny [z Wysockich?] Jentosiaków, rolników w Połoni, półtora roku, na nieznaną chorobę." },
    { id: "s1825-29", osoby: ["stanislaw-k", "helena-zyr", "kacper", "helena", "walenty"], y: 1825, k: "ślub", no: 29, g: 6, t: "Stanisław, syn Kacpra × Helena Żyrówna", fs: "https://www.familysearch.org/ark:/61903/3:1:3Q9M-CSXV-V955-G", r: "1 odczyt",
      q: "…inter HH Stanislaum Jentosiak juvenem an 19 filium Gaspari Jentosiak et Helenae Wysotka[?] L. C. in assistentia Parentum penes quos manet, et Helenam Zyrowna[?] virginem an 27…",
      tr: "24 lipca 1825 r. Ślub Stanisława Jentosiaka, kawalera, 19 lat, syna Kacpra i Heleny z Wysotków [?], mieszkającego przy rodzicach, z Heleną Żyrówną [?], panną, 27 lat, córką Andrzeja Żyry [?] i Agnieszki z Ułatowskich [?]. Świadek m.in. Walenty Antosiak, 26 lat. Kacper i Helena jeszcze żyli." },
    { id: "s1845-25", osoby: ["ewa-w", "jakub-banka", "walenty", "marianna-ch"], y: 1845, k: "ślub", no: 25, g: 5, t: "Ewa Antosiakówna × Jakub Bańka", scan: "4f677abc2fba85ecfbb1cc0fa86873439f4e79530c8dceed9618f988eaaebbde", r: "1 odczyt",
      q: "a panną Ewą Antosiakówną córką Walentego Antosiaka i Maryanny z Chudzików",
      tr: "1845 r. (data nadpalona). 21-letnia Ewa, córka Walentego i Marianny z domu Chudzik, mieszkająca przy rodzicach w Połoni, wychodzi za Jakuba Bańkę, 23 lata. Najstarsze znane dziecko Walentego — ur. ok. 1824." },
    { id: "z1827-28", osoby: ["wojciech-p", "pawel", "jadwiga", "marianna-grzyb", "karol"], y: 1827, k: "zgon", no: 28, g: 7, t: "Wojciech, syn Pawła i Jadwigi", scan: "ee5e3ba51b8d846a4d790baaac14f42234a20785d30f0da864aaea3eeae49b13", r: "1 odczyt",
      q: "Wojciech Antosiak włościanin rolny w Wsi Poloni, lat 70, syn niegdy Pawła i Jadwigi",
      tr: "15 lutego 1827 r. W Połoni zmarł Wojciech Antosiak, rolnik, 70 lat, syn zmarłych Pawła i Jadwigi. Zostawił wdowę Mariannę z Grzybów; zgon zgłosił syn Karol. Dowód, że Paweł i Jadwiga Antosiakowie żyli w Połoni." },
    { id: "u1827-50", osoby: ["jozef-w", "walenty", "marianna-ch", "wojciech-ch"], y: 1827, k: "chrzest", no: 50, g: 5, t: "Józef, pierwsze dziecko Walentego", scan: "3608549197d10ce393a66a9f90b77eac10d3abcf7b9a2303732b9c8727b3d8b1", r: "1 odczyt",
      q: "stawił się Walenty Jentosiak włościanin rolny w Wsi Połoni zamieszkały lat dwadzieścia osm",
      tr: "19 marca 1827 r. Przyszedł Walenty Jentosiak, rolnik z Połoni, 28 lat, i zgłosił syna Józefa, urodzonego tej nocy o 2. Matka: Marianna z domu Chudzik, 20 lat. Świadek: Wojciech Chudzik, krewny żony (hipoteza)." },
    { id: "z1828-174", osoby: ["kacper", "helena", "wojciech-k", "walenty"], y: 1828, k: "zgon", no: 174, g: 6, t: "Kacper Antosiak", scan: "50db82af2736851f2d16bbf4ce37196607573d6732dc3285a6291e99a7f54b76", r: "1 odczyt",
      q: "Umarł Kacper Antosiak … lat siedmdziesiąt mający, syn niewiadomych z imion rodziców, zostawiwszy po sobie owdowiałą żonę Helenę Antosiakową",
      tr: "14 listopada 1828 r. Synowie Wojciech (40) i Walenty (30) zgłosili, że wczoraj o 2 po południu zmarł w Połoni ich ojciec Kacper Antosiak, 70 lat. Imion jego rodziców nie znano. Zostawił wdowę Helenę." },
    { id: "z1829-58", osoby: ["mateusz-ch", "wojciech-ch", "walenty"], y: 1829, k: "zgon", no: 58, g: 5, t: "Mateusz Chudzik, ojciec Marianny", scan: "e749fef46a86006050eda3a89b6778890a8336a70aab1acce3abb805fcd15ac0", r: "1 odczyt",
      q: "stawili się Woyciech Chudzik stryj [?] zmarłego lat pięćdziesiąt, i Walenty Antosiak zięć zmarłego lat trzydzieści jeden",
      tr: "14 kwietnia 1829 r. (zgon 13 kwietnia) W Połoni zmarł Mateusz Chudzik, wdowiec, 80 lat, syn zmarłych Pawła i Barbary. Zgon zgłosili Wojciech Chudzik (50), w akcie „stryj” [?] zmarłego, i zięć Walenty Antosiak (31) — stąd wiemy, kim był ojciec Marianny. Dosłownie „stryj” jest niemożliwy (50-latek stryjem 80-latka); pisarz pewnie odwrócił relację (zmarły byłby stryjem Wojciecha). Wcześniejszy odczyt „syn zmarłego” był błędny — to słowo wygląda inaczej (litera po literze s-t-r-y-j)." },
    { id: "z1832-159", osoby: ["adam-p", "pawel", "jadwiga", "wojciech-a"], y: 1832, k: "zgon", no: 159, g: 7, t: "Adam, syn Pawła i Jadwigi", scan: "8f8a48975c34f250b4a8f49a2521b7908131ac2511cb9686b2bd6b28a52e098d", r: "1 odczyt",
      q: "Umarł Adam Antosiak w Połoni mieszkający lat Dziewięćdziesiąt mający, syn niegdy Pawła i Jadwigi",
      tr: "24 czerwca 1832 r. W Połoni zmarł Adam Antosiak, „90 lat”, syn zmarłych Pawła i Jadwigi. Zgon zgłosił jego syn Wojciech (27)." },
    { id: "z1832-150", osoby: ["jan-st", "stanislaw-k", "helena-zyr"], y: 1832, k: "zgon", no: 150, g: 6, t: "Jan, syn Stanisława (5 lat)", scan: "1d2fedff1fd9abf303fd04ff2e81de64568924679a80df6d12f104c5b09037a2", r: "2 odczyty",
      q: "Umarł Jan Antosiak lat pięć maiący, syn oświadczaiącego Stanisława Antosiaka, i Heleny z Żyrów Małżonków w Wsi Połoni mieszkaiących",
      tr: "19 czerwca 1832 r. (zgon 18 czerwca, 8 rano) w Połoni zmarł Jan Antosiak, 5 lat, syn Stanisława i Heleny z Żyrów. Zgłosili ojciec Stanisław (26) i Michał Bączek (30). Przyczyny akt nie podaje." },
    { id: "z1832-161", osoby: ["blazej-st", "stanislaw-k", "helena-zyr"], y: 1832, k: "zgon", no: 161, g: 6, t: "Błażej, syn Stanisława (6 miesięcy)", scan: "8f8a48975c34f250b4a8f49a2521b7908131ac2511cb9686b2bd6b28a52e098d", r: "2 odczyty",
      q: "Umarł Błażej Antosiak Miesięcy sześć maiący, syn oświadczaiącego Stanisława Antosiaka, i Heleny z Żyrów",
      tr: "28 czerwca 1832 r. (zgon 27 czerwca, w południe) w Połoni zmarł Błażej Antosiak, 6 miesięcy (ur. 3 lutego 1832, U 24/1832), syn Stanisława i Heleny z Żyrów. Zgłosili Stanisław (26) i Jan Bańka (33)." },
    { id: "z1832-163", osoby: ["katarzyna-st", "stanislaw-k", "helena-zyr"], y: 1832, k: "zgon", no: 163, g: 6, t: "Katarzyna, córka Stanisława (3,5 roku)", scan: "8f8a48975c34f250b4a8f49a2521b7908131ac2511cb9686b2bd6b28a52e098d", r: "2 odczyty",
      q: "Umarła Katarzyna Antosiakówna lat trzy i miesięcy sześć maiąca, córka oświadczaiącego Stanisława Antosiaka, i Heleny z Żyrów",
      tr: "29 czerwca 1832 r. (zgon 28 czerwca, 1 po południu) w Połoni zmarła Katarzyna Antosiakówna, 3 lata i 6 miesięcy (B 200/1829), córka Stanisława i Heleny z Żyrów. Zgłosili Stanisław (26) i Jan Bańka (33)." },
    { id: "u1834-116", osoby: ["jan-w", "walenty", "marianna-ch"], y: 1834, k: "chrzest", no: 116, g: 5, t: "Jan, syn Walentego", scan: "0905ad5492cff317a645637597a4997ec82099f963de15ee7e2bc228d284aca7", r: "1 odczyt",
      q: "z Jego Małżonki Maryanny z Chudzików lat trzydzieści mającej … nadane zostało Imię Jan",
      tr: "19 czerwca 1834 r., o 8 rano, w Połoni urodził się Jan, syn Walentego (ok. 36) i Marianny z Chudzików (30). Chrzestni: organista Mikołaj Fiałkowski i Marianna Antosiakówna. To ten Jan, który w 1853 r. ożenił się w Raszujce." },
    { id: "u1837-116", osoby: ["stanislaw-w", "walenty", "marianna-ch"], y: 1837, k: "chrzest", no: 116, g: 5, t: "Stanisław, syn Walentego", scan: "c3d60f5a30d57593e1010829b5feab759aaa1bdeb57124fcab5dad03757d7ac5", r: "1 odczyt",
      q: "stawił się Walenty Antosiak rolnik w Wsi Połoni lat trzydzieści osm mający … z jego Małżonki Maryanny z Chudzików lat trzydzieści pięć mającej",
      tr: "23 kwietnia 1837 r., o 7 rano, w Połoni urodził się Stanisław. Ojciec: Walenty Antosiak, rolnik, 38 lat; matka: Marianna z domu Chudzik, 35 lat. To ten Stanisław, który w 1862 r. ożenił się z Marianną Bączek." },
    { id: "s1837-28", osoby: ["andrzej-k", "ewa-winogrodzka", "kacper", "helena"], y: 1837, k: "ślub", no: 28, g: 6, t: "Andrzej, syn Kacpra × Ewa Winogrodzka", scan: "df4e28a181277e487f3b1a9c08984bfd3ebb8cf4c69f489d73ec107fc86c03a1", r: "1 odczyt",
      q: "synem niegdy Kacpra Antosiaka i żyjącej Heleny Małżonków lat czterdzieści pięć mającym",
      tr: "5/17 sierpnia 1837 r., Chorzele. Andrzej Antosiak, kawaler, robotnik najemny z Połoni, 45 lat, syn zmarłego Kacpra i żyjącej Heleny, żeni się z Ewą Winogrodzką, wdową, córką Piotra i Katarzyny Ludwików." },
    { id: "u1839-196", osoby: ["feliks", "walenty", "marianna-ch", "wojciech-ch"], y: 1839, k: "chrzest", no: 196, g: 4, t: "Feliks Antosiak", unit: 14110467, r: "1 odczyt",
      tr: "27 listopada 1839 r. w Połoni urodził się Feliks. Ojciec: Walenty, rolnik, 40 lat; matka: Marianna z domu Chudzik, 32 lata. Świadek: Wojciech Chudzik, rolnik z Połoni, 60 lat — krewny żony (hipoteza)." },
    { id: "s1841-9", osoby: ["stanislaw-k", "franciszka-senda", "kacper", "helena", "helena-zyr"], y: 1841, k: "ślub", no: 9, g: 6, t: "Stanisław Antosiak × Franciszka Sendówna", scan: "797a81b4914b13689dce961f1d6ddec8085ea0e41ca350952b0be248de9a3756", r: "2 odczyty",
      q: "…Stanisławem Antosiakiem wdowcem po zmarłej Helenie z Żyrów w dniu ósmym Października roku zeszłego, rolnikiem w Połoni mieszkającym i urodzonym z niegdy Kacpra Antosiaka i żyjącej Heleny z Fadorów [?] Małżonków synem lat trzydzieści cztery mającym",
      tr: "Luty 1841 r. Stanisław, wdowiec, brat Walentego, syn zmarłego już Kacpra i żyjącej Heleny, żeni się z 20-letnią sierotą Franciszką Sendówną z Budek. Zgodę na ślub wydała rada familijna Sądu Pokoju Powiatu Przasnyskiego. Z tego aktu wiemy, że Kacper zmarł przed 1841 r. Matka pana młodego, jeszcze żyjąca Helena, jest nazwana „z Fadorów” [?] — pierwsza litera nazwiska jest taka sama jak F w „Franciszką” dwie linie niżej. To wariant nazwiska Todor (Fedor = Teodor), nie „Wysocka”." },
    { id: "u1842-232", osoby: ["andrzej-w", "walenty", "marianna-ch", "wojciech-ch"], y: 1842, k: "chrzest", no: 232, g: 5, t: "Andrzej, syn Walentego", scan: "acaa36f5961352e353bd71869296382fee0bfe4c414903a91e4e7971ad9496e5", r: "2 odczyty",
      tr: "27 października / 8 listopada 1842 r., o 9 wieczorem, urodził się Andrzej, syn Walentego i Marianny z Chudzików. Chrzestni: Marcin Jenański i Marianna Łukasiakowa. Świadek: Wojciech Chudzik, krewny żony (hipoteza)." },
    { id: "u1843-175", osoby: ["rozalia-s", "grzegorz-s", "marianna-k", "aleksander-21"], y: 1843, k: "chrzest", no: 175, g: 4, t: "Rozalia Sędrowska", unit: 14110471, r: "1 odczyt",
      tr: "Ok. 1 października 1843 r. w Połoni urodziła się Rozalia, przyszła żona Feliksa. Ojciec: Grzegorz Sędrowski, 27 lat; matka: Marianna z domu Kuta, 23 lata. Ojciec chrzestny: Aleksander Antosiak, 22 lata (z innej gałęzi rodu)." },
    { id: "u1845-172", osoby: ["szczepan-w", "walenty", "marianna-ch", "stanislaw-k"], y: 1845, k: "chrzest", no: 172, g: 5, t: "Szczepan, syn Walentego", scan: "18a50f6c5193602b53cf9947a0fe2638e063a10e5ec7dbf2f80385ab3c2b0343", r: "2 odczyty",
      tr: "3 sierpnia 1845 r. urodził się Szczepan, syn Walentego i Marianny z Chudzików; ochrzczony następnego dnia. Chrzestni: Marcin J. i Franciszka Antosiakowa. Świadek: Stanisław Antosiak, 34 lata." },
    { id: "z1848-99", osoby: ["helena", "kacper", "wojciech-k", "stanislaw-k"], y: 1848, k: "zgon", no: 99, g: 6, t: "Helena, wdowa po Kacprze", scan: "8d46db95cadae674e143f0362b5b21f812d5e5419fd974954aaecf879c91cd43", r: "2 odczyty",
      q: "…córka niewiadomych z imion rodziców…",
      tr: "Maj 1848 r. W Połoni zmarła Helena Antosiakowa, wdowa po Kacprze, wyrobnica, urodzona w Połoni. Imion jej rodziców już nikt nie znał. Śmierć zgłosili jej synowie Wojciech i Stanisław („obadwa synowie zmarłej”)." },
    { id: "s1850-5", osoby: ["wawrzyniec-w2", "katarzyna-l", "walenty", "marianna-ch"], y: 1850, k: "ślub", no: 5, g: 5, t: "Wawrzyniec Antosiak × Katarzyna Łukowska", scan: "806088f9a3389112626eba04dcd7818e674a53f98d944435b7e21a769f98f40e", r: "2 odczyty",
      tr: "15/27 stycznia 1850 r. Wawrzyniec, najstarszy znany syn Walentego, ok. 20 lat, żeni się z 21-letnią Katarzyną. Świadkowie: Adam Wróbel (50) i Szymon Majewski (45). W późniejszych aktach jej nazwisko zapisano jako „z Żołowskich”." },
    { id: "u1850-157", osoby: ["aleksander-w", "walenty", "marianna-ch"], y: 1850, k: "chrzest", no: 157, g: 5, t: "Aleksander, syn Walentego", scan: "307debe71048803876385eddda123af4d4744c675c3ece738f685c8d2bb2e9b2", r: "1 odczyt",
      tr: "Sierpień 1850 r. Urodził się Aleksander, najmłodszy znany syn Walentego i Marianny. Chrzestni: Jan Gotart(?) i Franciszka Antosiakowa." },
    { id: "u1844-68", osoby: ["franciszek-wa", "wojciech-a", "marianna-baczek"], y: 1844, k: "chrzest", no: 68, g: 5, t: "Franciszek, syn Wojciecha", scan: "5bbde93320f902b28a040cd64eb9dc4598b4b7963f683aa39d7ce0988c0c9aab", r: "1 odczyt",
      tr: "6/7 kwietnia 1844 r. Wojciech Antosiak, rolnik, 40 l., zgłosił syna Franciszka z żony Maryanny z Bączków (30 l.). Chrzestni: Wojciech Bączek i Ewa." },
    { id: "u1846-192", osoby: ["agata-ka", "karol", "marianna-golab"], y: 1846, k: "chrzest", no: 192, g: 5, t: "Agata, córka Karola", scan: "1590beca44244d435684d9953dffdf2511de85f5d994bd0395891f5335c3022d", r: "1 odczyt",
      tr: "19/20 grudnia 1846 r. Karol Antosiak, 46 l., zgłosił córkę Agatę z żony Maryanny z Gołębiewskich (34 l.). Świadek Wojciech Antosiak; chrzestni Józef Gołębiewski i Maryanna." },
    { id: "u1850-116", osoby: ["urszula-wa", "wojciech-a", "marianna-baczek"], y: 1850, k: "chrzest", no: 116, g: 5, t: "Urszula, córka Wojciecha", scan: "1ea69482e040ab6a2fd9dc02ee15d135aae04fafe82f0991fd9ba756e449e6a7", r: "1 odczyt",
      tr: "12/13 czerwca 1850 r. Wojciech Antosiak, 47 l., zgłosił córkę Urszulę z żony Maryanny z Bączków (35 l.). Chrzestni: Wojciech Bączek i Ewa." },
    { id: "z1852-59", osoby: ["wojciech-k", "kacper", "helena", "jan-banka", "walenty"], y: 1852, k: "zgon", no: 59, g: 6, t: "Wojciech, syn Kacpra", scan: "f34056e7c68c7d26eb93100e5a5881a86fa8feebf5341b09a3c34148041ab8de", r: "1 odczyt",
      q: "umarł Wojciech Antosiak Wyrobnik lat sześćdziesiąt żyjący, syn nieżyjących Kacpra i Heleny",
      tr: "Kwiecień 1852 r. W Połoni zmarł Wojciech Antosiak, robotnik najemny, 60 lat, syn nieżyjących już Kacpra i Heleny. Śmierć zgłosili Jan Bańka (60, szwagier) i Walenty Antosiak (50, brat)." },
    { id: "s1853-34", osoby: ["jan-w", "marianna-sz", "walenty", "marianna-ch"], y: 1853, k: "ślub", no: 34, g: 5, t: "Jan Antosiak × Marianna Szlagowa", scan: "ee9d3ebfb969ae7f63664f3e940bcf28c19df7c2ff56c657c04b4da4dc060c33", r: "1 odczyt",
      q: "…Janem Antosiakiem młodzianem synem Walentego i Maryanny z Chudzików…",
      tr: "28 czerwca / 10 lipca 1853 r. 19-letni kawaler Jan, syn Walentego i Marianny z domu Chudzik, żeni się z 40-letnią wdową Marianną Szlagową z domu Piórkowską i zamieszkuje w Raszujce. Rodzice Jana zgodzili się na ślub ustnie — oboje wtedy żyli." },
    { id: "u1854-109", osoby: ["anna-j", "jan-w", "marianna-sz", "walenty"], y: 1854, k: "chrzest", no: 109, g: 5, t: "Anna, wnuczka Walentego", scan: "974da984fc09400068b4b6a0937f94850b9cdc9b248221b03324532b93517f73", r: "1 odczyt",
      q: "Rodzicami jego Chrzestnemi byli Walenty Antosiak i Ewa Piórkowska",
      tr: "Kwiecień 1854 r., Raszujka. Urodziła się Anna, córka Jana Antosiaka (20, rolnik) i Marianny z Piórkowskich. Rodzicami chrzestnymi byli Walenty Antosiak — dziadek — i Ewa Piórkowska." },
    { id: "z1855-34", osoby: ["rozalia-k", "jan-banka", "kacper", "helena", "stanislaw-k"], y: 1855, k: "zgon", no: 34, g: 6, t: "Rozalia Bańkowa z Antosiaków", scan: "bb89f86f26668418e1b7cb9cf760a7351f68b7f5858fe0bb4eb3c5a876fc9d86", r: "1 odczyt",
      tr: "8/20 lutego 1855 r. Zmarła Rozalia Bańkowa, ok. 60 lat, córka Kacpra i Heleny Antosiaków, żona Jana Bańki. Świadkiem był jej brat Stanisław Antosiak (50)." },
    { id: "z1856-59", osoby: ["wawrzyniec-w2", "katarzyna-l", "adam-ww"], y: 1856, k: "zgon", no: 59, g: 5, t: "Wawrzyniec, syn Walentego", scan: "fe9bcb6988164c2e6ed280f6145030bb4f35068f596195e6cb6ab13aec2cae79", r: "1 odczyt",
      tr: "8/20 maja 1856 r. Zmarł Wawrzyniec Antosiak, wyrobnik z Połoni, wiek zapisany jako 24 lata. Pozostawił wdowę Katarzynę z Żołowskich i 3-letniego syna Adama." },
    { id: "z1861-91", osoby: ["walenty", "marianna-ch", "kacper", "helena", "jakub-banka"], y: 1861, k: "zgon", no: 91, g: 5, t: "Walenty Antosiak", scan: "d558a5f61137663c08a107899f8d590bed79fe724d4cf2986884da1ed8fe77b2", r: "sprawdzone",
      q: "umarł w Połoni Walenty Antosiak rolnik lat sześćdziesiąt… tamże urodzony — Syn niegdy Kacpra i Heleny Antosiaków — Pozostawił owdowiałą żonę Maryannę z Chudzików",
      tr: "2 października 1861 r. W Połoni zmarł Walenty Antosiak, rolnik, 60 lat, urodzony w Połoni, syn zmarłych Kacpra i Heleny. Zostawił wdowę Mariannę z domu Chudzik. Śmierć zgłosili sąsiedzi Jakub Bańka (36) i Walenty Bańka (32)." },
    { id: "s1862-24", osoby: ["stanislaw-w", "marianna-b", "walenty", "marianna-ch"], y: 1862, k: "ślub", no: 24, g: 5, t: "Stanisław Antosiak × Marianna Bączek", scan: "45d427503d692c9e8ea40cdfe24ac3f4838335c6e7cf153d4158bb2cd4a73c5e", r: "1 odczyt",
      q: "…synem niegdy Walentego i żyjącej Maryanny z Chudzików…",
      tr: "9 lutego 1862 r. 25-letni kawaler Stanisław, syn zmarłego Walentego i żyjącej Marianny, żeni się z 21-letnią Marianną Bączek, córką Stanisława i Antoniny. Świadkowie: Jakub Bańka i Adam Obrębski." },
    { id: "s1864-28", osoby: ["feliks", "rozalia-s", "walenty", "marianna-ch", "jakub-banka"], y: 1864, k: "ślub", no: 28, g: 4, t: "Feliks Antosiak × Rozalia Sendrowska", scan: "24b94c89cdc0d01a14405d18cd6de2772722d1fcd12071917314238d3b334d54", r: "sprawdzone",
      q: "…Feliksem Antosiakiem młodzianem, synem niegdy Walentego i żyjącej Maryanny z Chudzików…",
      tr: "7 lutego 1864 r., Chorzele. 24-letni kawaler Feliks, syn zmarłego Walentego i żyjącej Marianny, gospodarujący przy matce w Połoni, żeni się z 20-letnią Rozalią Sendrowską, mieszkającą przy rodzicach. Świadkowie: Jakub Bańka i Mikołaj Wróbel; ślubu udzielił ks. Romuald Kiersnowski." },
    { id: "u1868-104", osoby: ["franciszek", "feliks", "rozalia-s"], y: 1868, k: "chrzest", no: 104, g: 3, t: "Franciszek Antosiak", idx: true, url: "https://metryki.genealodzy.pl/id1483-sy1868-kt1",
      tr: "5 maja 1868 r., Połoń. Od 1868 r. akty pisano po rosyjsku. Akt znamy z indeksu Geneteki; skan księgi jest w serwisie metryki.genealodzy.pl (nieprzeczytany)." },
    { id: "u1905-271", osoby: ["wincenty", "franciszek", "marcjanna-l"], y: 1905, k: "chrzest", no: 271, g: 2, t: "Wincenty Antosiak", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1483&sy=1905&kt=1&plik=271-272.jpg", r: "1 odczyt",
      q: "…Iavilsia lichno Frantsishek Antosiak, zemledelets iz derevni Polon', tridtsati semi let ot rodu…",
      tr: "4/17 grudnia 1905 r., Chorzele. Franciszek Antosiak, rolnik z Połoni, 37 lat, okazał syna urodzonego w Połoni 2/15 grudnia o 4 po południu z żony Marcjanny z Lipków, 30 lat; nadano mu imię Wincenty. Świadkowie: Wincenty i Aleksander Bańkowie; chrzestni: Wincenty Bańka i Marianna Bączek." },
    { id: "s1925-40", osoby: ["wincenty", "eleonora", "franciszek", "marcjanna-l", "adam-d", "marianna-o", "wladyslaw-f"], y: 1925, k: "ślub", no: 40, g: 2, t: "Wincenty Antosiak × Eleonora Dębek", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1483&sy=1925&kt=2&plik=040-041.jpg", r: "1 odczyt",
      q: "zawarte zostało w dniu dzisiejszym religijne małżeństwo pomiędzy Wincentym Antosiakiem, kawalerem, lat dziewiętnaście, synem Franciszka i Marcjanny z Lipków małżonków Antosiaków … i Eleonorą Dębek, panną, lat dwadzieścia jeden, córką Adama i Marjanny z Obrębskich małżonków Dębków",
      tr: "16 sierpnia 1925 r., Chorzele. Akt już po polsku. Wincenty, 19 lat, i Eleonora, 21 lat, oboje z Połoni. Rodzice niepełnoletniego pana młodego zgodzili się ustnie. Świadkowie: Piotr Walczyk [?] i Władysław Antosiak, brat pana młodego. Na marginesie późniejszy dopisek o zgonie Eleonory w 1988 r. (miejsce odczytane niepewnie)." },
    { id: "z1926-105", osoby: ["franciszek", "feliks", "rozalia-s", "marcjanna-l"], y: 1926, k: "zgon", no: 105, g: 3, t: "Franciszek Antosiak", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1483&sy=1926&kt=3&plik=103-106.jpg", r: "1 odczyt",
      q: "umarł w Połoni Franciszek Antosiak, lat pięćdziesiąt siedem, gospodarz, syn Feliksa i Rozalji z Sędrowskich małżonków Antosiaków, urodzony i zamieszkały w Połoni. Zostawił owdowiałą żonę Marcjannę z Lipków",
      tr: "25 września 1926 r., Chorzele. Onegdaj, 23 września o 12 w południe, zmarł w Połoni Franciszek Antosiak, 57 lat. Zgłosili Aleksander Antosiak [36 lat?] i Stanisław Bańka." },
    { id: "z1880-273", osoby: ["feliks", "walenty", "marianna-ch", "rozalia-s"], y: 1880, k: "zgon", no: 273, g: 4, t: "Feliks Antosiak", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1483&sy=1880&kt=3&plik=271-273.jpg", r: "1 odczyt",
      q: "…umer v derevne Polon' Feliks Antosiak, zemledelets sorok odnogo let ot rodu, syn pokoinykh Valentago i Mariianny suprugov Antosiakov…",
      tr: "12/24 grudnia 1880 r., Chorzele. Wczoraj, 11/23 grudnia o 8 wieczorem, zmarł w Połoni Feliks Antosiak, rolnik, 41 lat, urodzony w Połoni, syn zmarłych Walentego i Marianny. Zostawił wdowę Rozalię z Sendrowskich. Zgon zgłosili Aleksander Antosiak, 30 lat, i Paweł [?] Obrębski, 50 lat." },
    { id: "s1892", osoby: ["franciszek", "marcjanna-l", "feliks", "rozalia-s", "franciszek-lip", "franciszka-fuks"], y: 1892, k: "ślub", no: 20, g: 3, t: "Franciszek Antosiak × Marcjanna Lipka", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1483&sy=1892&kt=2&plik=020.jpg", r: "1 odczyt",
      q: "…mezhdu Frantsishkom Antosiak … synom pokoinago Feliksa Antosiak i nakhodiashcheisia v zhivykh ego zheny Rozalii iz Sendrovskikh, dvadtsati trekh let ot rodu, i Martsiannoiu Lipka, devitseiu … docher'iu pokoinago Frantsishka Lipki i nakhodiashcheisia v zhivykh ego zheny Frantsishki iz Fuksov, deviatnadtsati let ot rodu.",
      tr: "26 stycznia / 7 lutego 1892 r., Chorzele. Franciszek Antosiak, kawaler, rolnik z Połoni, 23 lata, syn zmarłego Feliksa i żyjącej Rozalii z Sendrowskich, żeni się z Marcjanną Lipką, panną, 19 lat, urodzoną i mieszkającą w Połoni przy matce, córką zmarłego Franciszka Lipki i żyjącej Franciszki z Fuksów. Matka panny zgodziła się ustnie. Ślubu udzielił ks. Antoni Morawski." },
    { id: "s1909-4", osoby: ["aleksander-sz", "katarzyna-sz", "franciszek-szcz", "marianna-ploch", "jozef-radz", "agnieszka-rataj", "antonina-sz", "marta-sz"], parish: "Nowa Wieś k. Ostrołęki", y: 1909, k: "ślub", no: 4, g: null, t: "Aleksander Szczepanek × Katarzyna Radziejewska", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1509&sy=1909&kt=2&plik=004.jpg", r: "1 odczyt",
      q: "…docieri Antoninu imiejuszczuju ot rodu dwa goda i Martu imiejuszczuju ot rodu odin god, rodiwszijesia w Prussii…",
      tr: "12/25 stycznia 1909 r., Nowa Wieś. Aleksander Szczepanek, 25 lat, kawaler, syn Franciszka i Marianny z Płocharczyków, urodzony i mieszkający w Chojnikach przy rodzicach, żeni się z Katarzyną Radziejewską, 23 lata, panną, córką Józefa i Agnieszki z Ratajów, z Mostowa. Nowożeńcy uznali za swoje córki urodzone przed ślubem w Prusach: Antoninę, 2 lata, i Martę, rok. To dziadkowie babci Henryki." },
    { id: "u1913-10", osoby: ["zofia-m", "aleksander-sz", "katarzyna-sz"], parish: "Nowa Wieś k. Ostrołęki", y: 1913, k: "chrzest", no: 10, g: null, t: "Zofia Szczepanek, matka babci Henryki", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1509&sy=1913&kt=1&plik=009-010.jpg", r: "1 odczyt",
      q: "…ot zakonnoj jego żeny Jekateriny urożdionnoj Radziejewskoj (Katarzyny z Radziejewskich) dwadcati szesti let ot rodu. Mładiencu etomu … dano imia Sofija (Zofia)…",
      tr: "13/26 stycznia 1913 r., Nowa Wieś. Aleksander Szczepanek, 30 lat, morgownik z Chojnik, zgłosił córkę urodzoną w Chojnikach 6/19 stycznia 1913 r. o 14 z jego żony Katarzyny z Radziejewskich, 26 lat. Na chrzcie dano jej imię Zofia; chrzestni: Franciszek i Katarzyna Szczepankowie. Świadkowie: Jan i Teofil Cekałowie, morgownicy z Chojnik." },
    { id: "z1871-115", osoby: ["marianna-ch", "walenty", "mateusz-ch", "feliks", "jozef-w"], y: 1871, k: "zgon", no: 115, g: 5, t: "Marianna z Chudzików, wdowa po Walentym", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1483&sy=1871&kt=3&plik=115-117.jpg", r: "1 odczyt",
      q: "…umerla v derevne Budki Mar'ianna Antosiak … semidesiati let ot rodu, doch' pokoinago Matveia Khudzika i neizvestnoi materi, vdova po Valentii Antosiak.",
      tr: "13/25 września 1871 r., Chorzele. 9/21 września o 4 po południu zmarła we wsi Budki Marianna Antosiak, 70 lat, mieszkająca przy synu, córka zmarłego Mateusza Chudzika i nieznanej matki, wdowa po Walentym Antosiaku. Zgon zgłosili Józef Antosiak, 43 lata, i Feliks Antosiak, 30 lat — jej synowie." },
    { id: "s1891-49", osoby: ["rozalia-s", "feliks", "grzegorz-s", "marianna-k"], y: 1891, k: "ślub", no: 49, g: 4, t: "Rozalia, wdowa po Feliksie × Jan Rybiński", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1483&sy=1891&kt=2&plik=049.jpg", r: "1 odczyt",
      q: "…i Rozalieiu Antosiak, zemledelitseiu, vdovoiu po umershem v derevne Polon' … muzhe Felikse Antosiak…",
      tr: "4/16 sierpnia 1891 r., Chorzele. Jan Rybiński, wdowiec z Łazu, urodzony w Budkach, syn zmarłych Adama i Ewy z Rogalskich, żeni się z Rozalią Antosiak, wdową po Feliksie zmarłym w Połoni 11/23 grudnia 1880 r., córką zmarłych Grzegorza i Marianny Sendrowskich." },
    { id: "z1907-38", osoby: ["rozalia-s", "grzegorz-s", "marianna-k"], y: 1907, k: "zgon", no: 38, g: 4, t: "Rozalia Rybińska z Sendrowskich", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1483&sy=1907&kt=3&plik=037-038.jpg", r: "1 odczyt",
      q: "…umerla v derevne Laz Rozaliia Rybinskaia, zemledelitsa, shestidesiati piati let ot rodu, doch' pokoinykh Grigoriia i Mariianny suprugov Sendrovskikh, rodivshaiasia v derevne Polon'…",
      tr: "12/25 lutego 1907 r., Chorzele. Dziś o 8 rano zmarła we wsi Łaz Rozalia Rybińska, rolniczka, 65 lat, córka zmarłych Grzegorza i Marianny Sendrowskich, urodzona w Połoni. Zostawiła męża Jana Rybińskiego, który zgłosił zgon razem z Piotrem Rybińskim." },
    { id: "u1895-45", osoby: ["franciszek-f", "franciszek", "marcjanna-l"], y: 1895, k: "chrzest", no: 45, g: 3, t: "Franciszek, syn Franciszka", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1483&sy=1895&kt=1&plik=043-045.jpg", r: "1 odczyt",
      q: "…ot zakonnoi ego zheny Martsianny urozhdennoi Lipka, dvadtsati dvukh let ot rodu. Mladentsu semu … dano imia Frantsishek…",
      tr: "5/17 lutego 1895 r., Chorzele. Wczoraj, 4/16 lutego o 4 po południu, urodził się w Połoni syn Franciszka Antosiaka, 26 lat, i Marcjanny z Lipków, 22 lata; dano mu imię Franciszek. Chrzestni: Mateusz Antosiak z żoną Małgorzatą. Na marginesie: zmarł 10 lutego 1962 r. w Połoni (USC Chorzele, akt 14/1962)." },
    { id: "u1903-230", osoby: ["eleonora", "adam-d", "marianna-o"], y: 1903, k: "chrzest", no: 230, g: 2, t: "Eleonora Dębek", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1483&sy=1903&kt=1&plik=229-230.jpg", r: "1 odczyt",
      q: "…Iavilsia lichno Adam Dembek /Adam Dębek/, zemledelets iz derevni Polon', dvadtsati piati let ot rodu…",
      tr: "5/18 października 1903 r., Chorzele. Adam Dębek, rolnik z Połoni, 25 lat, okazał córkę urodzoną wczoraj, 4/17 października o 9 wieczorem, z żony Marianny z Obrębskich, 19 lat; nadano jej imię Eleonora. Chrzestni: Adam Majewski z żoną Katarzyną." },
    { id: "s1902-35", osoby: ["adam-d", "marianna-o", "grzegorz-d", "rozalia-mierz", "wawrzyniec-obr", "malgorzata-bak"], y: 1902, k: "ślub", no: 35, g: 3, t: "Adam Dębek × Marianna Obrębska", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1483&sy=1902&kt=2&plik=035.jpg", r: "1 odczyt",
      q: "…mezhdu: Adamom Dembek /Adam Dębek/, kholostym … synom pokoinago Grigoriia Dembek /Grzegorza Dębek/ i nakhodiashcheisia v zhivykh ego zheny Rozalii urozhdennoi Merzheevskoi /Rozalii z Mierzejewskich/…",
      tr: "12/25 maja 1902 r., Chorzele. Adam Dębek z Połoni, kawaler, syn zmarłego Grzegorza i żyjącej Rozalii z Mierzejewskich, żeni się z Marianną Obrębską, 17 lat, z Olszewki, córką Wawrzyńca i Małgorzaty z Bakułów. Umowę przedślubną zawarto u notariusza w Przasnyszu. Na marginesie: Marianna zmarła 16.11.1961 w Połoni." },
    { id: "s1925-15", osoby: ["wladyslaw-f", "marcjanna-pog", "franciszek", "marcjanna-l", "franciszek-f"], y: 1925, k: "ślub", no: 15, g: 3, t: "Władysław Antosiak × Marianna Suchowiecka", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1483&sy=1925&kt=2&plik=014-015.jpg", r: "1 odczyt",
      q: "pomiędzy: Władysławem Antosiakiem, kawalerem, gospodarzem, lat dwadzieścia cztery, synem Franciszka i Marcjanny z Lipków … i Marjanną Suchowiecką, wdową, gospodynią, lat dwadzieścia siedem, córką Antoniego i Katarzyny z Bojarskich małżonków Pogorzelskich",
      tr: "22 lutego 1925 r., Chorzele. Przyszły wójt Władysław, 24 lata, żeni się z wdową Marianną Suchowiecką z Pogorzelskich, 27 lat, z Olszewki. Świadek: Franciszek Antosiak, 28 lat — brat pana młodego." },
    { id: "s1870-36", osoby: ["franciszek-lip", "franciszka-fuks", "samuel-lip", "ludwika-luma", "gotlib-fuks", "marianna-bratek"], y: 1870, k: "ślub", no: 36, g: 4, t: "Franciszek Lipka × Franciszka Fuks", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1483&sy=1870&kt=2&plik=36-37.jpg", r: "1 odczyt",
      q: "…synom Samuila Lipki /Samuela Lipki/ i Lovizy /Lowizy/ urozhdennoi Liumovoi /z Lümów/ … urozhentsem Prusskago Korolevstva, derevni Linovo…",
      tr: "27 lutego 1870 r., Chorzele. Franciszek Lipka, 25 lat, kawaler, syn Samuela Lipki i Lowizy z Lümów, rolników z Połoni, urodzony w Królestwie Pruskim we wsi Linowo [?], żeni się z Franciszką Fuks, 28 lat, z Budek, córką zmarłego Gotliba Fuksa i Marianny z Bratków. Zwykły ślub katolicki — akt nic nie mówi o wyznaniu." },
    { id: "u1872-107", osoby: ["marcjanna-l", "franciszek-lip", "franciszka-fuks"], y: 1872, k: "chrzest", no: 107, g: 3, t: "Marcjanna Lipka", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1483&sy=1872&kt=1&plik=107-108.jpg", r: "1 odczyt",
      q: "…Iavilsia lichno Frantsishek Lipka /Franciszek Lipka/, podenshchik zhitel'stvuiushchii v derevne Polon', dvadtsati semi let…",
      tr: "18/30 maja 1872 r., Chorzele. Franciszek Lipka, wyrobnik z Połoni, 27 lat, okazał córkę urodzoną 16/28 maja o 10 wieczorem z żony Franciszki z Fuksów, 30 lat; nadano jej imię Marcjanna. Chrzestni: Aleksander i Marcjanna Antosiakowie." },
    { id: "s1878-17", osoby: ["franciszka-fuks", "franciszek-lip", "gotlib-fuks", "marianna-bratek"], y: 1878, k: "ślub", no: 17, g: 4, t: "Franciszka z Fuksów, wdowa × Paweł Sobieraj", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1483&sy=1878&kt=2&plik=017-018.jpg", r: "1 odczyt",
      tr: "12/24 lutego 1878 r. [?], Chorzele. Paweł Sobieraj, robotnik z Jednorożca, żeni się z Franciszką Lipką, wdową po Franciszku Lipce zmarłym w marcu 1876 lub 1877 r., córką zmarłego Gotliba („Gottlieb”) Fuksa i Marianny z Bratków, z Budek. Odczyt częściowy." },
    { id: "s1916-5", osoby: ["jozefa-radz", "jozef-radz", "agnieszka-rataj"], parish: "Nowa Wieś k. Ostrołęki", y: 1916, k: "ślub", no: 5, g: null, t: "Józefa Radziejewska × Józef Banach", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1509&sy=1915&kt=4&plik=005-006.jpg", r: "1 odczyt",
      q: "…i Józefą Radziejewską panną dwadzieścia jeden rok mającą, urodzoną w Mostowie i tam zamieszkałą przy rodzicach gospodarzach, córką Józefa i Agnieszki z Ratajów małżonków Radziejewskich.",
      tr: "1916 r., Nowa Wieś. Józefa Radziejewska, 21 lat, z Mostowa, córka Józefa i Agnieszki z Ratajów — prawdopodobnie siostra Katarzyny, babki babci Henryki — wychodzi za Józefa Banacha z Grabówka." },
    { id: "z1909-70", osoby: ["marianna-ploch", "franciszek-szcz", "grzegorz-ploch", "franciszka-szlach"], parish: "Nowa Wieś k. Ostrołęki", y: 1909, k: "zgon", no: 70, g: null, t: "Marianna Szczepankowa z Płocharczyków", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1509&sy=1909&kt=3&plik=069-070.jpg", r: "1 odczyt",
      tr: "Chojniki, 16/29 grudnia 1909 r., o 6 rano. Zmarła Marianna Szczepanek z domu Płocharczyk, gospodyni, 66 lat, urodzona w Rżańcu, córka zmarłych Grzegorza Płocharczyka i Franciszki ze Szlachetków, żona Franciszka. To matka Aleksandra — rok wcześniej była przy jego ślubie." },
    { id: "s1911-17", osoby: ["franciszek-szcz", "piotr-szcz", "marianna-radoch"], parish: "Nowa Wieś k. Ostrołęki", y: 1911, k: "ślub", no: 17, g: null, t: "Franciszek Szczepanek, wdowiec × Małgorzata Szczygieł", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1509&sy=1911&kt=2&plik=017.jpg", r: "1 odczyt",
      tr: "1911 r., Nowa Wieś. Franciszek Szczepanek, 57 lat, urodzony w Wyszlu, syn Piotra i Marianny z Radochów, wdowiec po Mariannie z Płocharczyków, żeni się z Małgorzatą Szczygieł z Kokiernaków, wdową, 54 lata, z Mostowa." },
    { id: "z1911-28", osoby: ["antonina-sz", "aleksander-sz", "katarzyna-sz"], parish: "Nowa Wieś k. Ostrołęki", y: 1911, k: "zgon", no: 28, g: null, t: "Antonina Szczepanek, 5 lat", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1509&sy=1911&kt=3&plik=027-028.jpg", r: "1 odczyt",
      tr: "Chojniki, 11/24 maja 1911 r. Zmarła Antonina, 5 lat, córka Aleksandra i Katarzyny Szczepanków, urodzona w Prusach. Zgłosili Jan i Teofil Cekałowie z Chojnik." },
    { id: "z1911-33", osoby: ["marta-sz", "aleksander-sz", "katarzyna-sz", "franciszek-szcz"], parish: "Nowa Wieś k. Ostrołęki", y: 1911, k: "zgon", no: 33, g: null, t: "Marta Szczepanek, 3 lata", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1509&sy=1911&kt=3&plik=033-034.jpg", r: "1 odczyt",
      tr: "Chojniki, 28 maja / 10 czerwca 1911 r. — 17 dni po siostrze. Zmarła Marta, 3 lata, córka Aleksandra i Katarzyny, urodzona w Prusach. Zgłosili Franciszek Szczepanek, 58 lat (pasuje na dziadka), i Jan Wójcik." },
    { id: "z1917-9", osoby: ["jozef-radz", "jan-radz", "rozalia-andrz", "agnieszka-rataj"], parish: "Nowa Wieś k. Ostrołęki", y: 1917, k: "zgon", no: 9, g: null, t: "Józef Radziejewski", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1509&sy=1917&kt=5&plik=007-010.jpg", r: "1 odczyt",
      tr: "Mostowo, 26 marca 1917 r. Zmarł Józef Radziejewski, „na gospodarstwie”, 66 lat, urodzony w Mostowie, syn Jana i Rozalii z Andrzejczyków; zostawił żonę Agnieszkę z Ratajów. Ojciec Katarzyny, babki babci Henryki." },
    { id: "z1931-17", osoby: ["franciszek-szcz", "piotr-szcz", "marianna-radoch"], parish: "Nowa Wieś k. Ostrołęki", y: 1931, k: "zgon", no: 17, g: null, t: "Franciszek Szczepanek", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1509&sy=1931&kt=3&plik=017-020.jpg", r: "1 odczyt",
      tr: "Chojniki, 4 kwietnia 1931 r. (spisano 7 kwietnia), o 8 rano. Zmarł Franciszek Szczepanek, 82 lata, urodzony i zamieszkały w Chojnikach, syn Piotra i Marianny z Radochów. Ojciec Aleksandra." },
    { id: "u1904-20", osoby: ["wladyslaw-m", "adam-mie", "elzbieta-gas"], parish: "Nowa Wieś k. Ostrołęki", y: 1904, k: "chrzest", no: 20, g: null, t: "Władysław Mieszała, syn Adama (ścieżka A)", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1509&sy=1904&kt=1&plik=019-020.jpg", r: "1 odczyt",
      tr: "Grabówko, 21 lutego / 5 marca 1904 r. Urodził się Władysław, syn Adama Mieszały, rolnika, 37 lat, i Elżbiety z Gąsków, 34 lata. Chrzestni: Adam Kizember [?] i Katarzyna. Ścieżka A do pradziadka Adriana — prawdopodobna (m.in. wujek Leopold z relacji rodzinnej)." },
    { id: "s1936-6", osoby: ["leopold-mie", "adam-mie", "elzbieta-gas", "adolfa-mie"], parish: "Nowa Wieś k. Ostrołęki", y: 1936, k: "ślub", no: 6, g: null, t: "Leopold Mieszała × Jadwiga Wieczorek (brat ścieżki A)", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1509&sy=1936&kt=2&plik=006-007.jpg", r: "1 odczyt",
      q: "w obecności świadków Stefana Tabaki organisty z Nowejwsi lat czterdzieści dwa i Józefa Drężka rolnika z Chojnik lat trzydzieści cztery ... pomiędzy Leopoldem Mieszałą kawalerem rolnikiem lat dwadzieścia pięć, urodzonym i zamieszkałym w Grabówku, synem Adama i Elżbiety z Gąsków małżonków Mieszałów, a Jadwigą Wieczorek panną przy rodzicach lat dwadzieścia jeden, urodzoną w Rawach parafii Gąsewo a zamieszkałą w Rżańcu, córką Józefa i Zofii z Strzeleckich",
      tr: "23 kwietnia 1936 r., Nowa Wieś. Leopold Mieszała, 25 lat, kawaler, rolnik z Grabówka, syn Adama i Elżbiety z Gąsków, żeni się z Jadwigą Wieczorek, 21 lat, panną z Rżańca (ur. w Rawach, parafia Gąsewo), córką Józefa i Zofii ze Strzeleckich. Świadkowie: Stefan Tabaka, organista (42), i Józef Drężek, rolnik z Chojnik (34) — mąż Adolfy, siostry Leopolda. Według relacji rodzinnej Leopold był bratem ojca babci Henryki i jej ojcem chrzestnym; jedyny Leopold Mieszała w parafii — to wskazuje na ścieżkę A. Władysława wśród świadków brak (to nic nie przesądza)." },
    { id: "u1904-53", osoby: ["wladyslaw-m", "piotr-mie", "wiktoria-gla"], parish: "Nowa Wieś k. Ostrołęki", y: 1904, k: "chrzest", no: 53, g: null, t: "Władysław Mieszała, syn Piotra (ścieżka B)", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1509&sy=1904&kt=1&plik=053-054.jpg", r: "1 odczyt",
      tr: "Grabówko, 15/28 czerwca 1904 r. Urodził się Władysław, syn Piotra Mieszały, 40 lat, i Wiktorii z Gładków, 28 lat. Chrzestni: Walenty i Katarzyna Mieszałowie. Ścieżka B do pradziadka Adriana — hipoteza." },
    { id: "u1916-1", osoby: ["eugeniusz-mie", "piotr-mie"], parish: "Nowa Wieś k. Ostrołęki", y: 1916, k: "chrzest", no: 1, g: null, t: "Eugeniusz Mieszała, ur. w czasie ruchu wojennego", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1509&sy=1915&kt=1&plik=SkU.jpg", r: "1 odczyt",
      q: "…urodzone jest w Szlągach [?] parafii Czerwin w czasie ruchu wojennego na dniu czwartym sierpnia roku zeszłego…",
      tr: "1916 r., Nowa Wieś. Piotr Mieszała z Grabówka zgłasza syna Eugeniusza, urodzonego 4 sierpnia 1915 r. w Stylągach [?] w parafii Czerwin „w czasie ruchu wojennego” — rodzina uciekała przed frontem. Brat Władysława z aktu 53/1904." },
    { id: "z1902-302", osoby: [], parish: "Myszyniec", y: 1902, k: "zgon", no: 302, g: null, t: "Stanisław Mieszała, 10 miesięcy (Dąbrowy)", scan: "6d653dc77fe49c329cbf1fbbac978574f505ec1c8136d6e53ca3d9e50015469f", r: "1 odczyt",
      q: "Мѣшала … (Stanisław Mieszała)",
      tr: "14/27 grudnia 1902 r., parafia Myszyniec, akt po rosyjsku. W Dąbrowach zmarł Stanisław Mieszała, 10 miesięcy. Matka: Rozalia Mieszała, właścicielka rolna w Dąbrowach (nazwisko rodowe ucięte na skanie); ojca akt nie wymienia. Pierwszy pewny ślad Mieszałów w Dąbrowach ok. 1900 r. Związek z babcią Henryką to wciąż hipoteza." },
    { id: "s1926-36", osoby: ["aleksander-f", "marianna-f", "franciszek", "marcjanna-l"], y: 1926, k: "ślub", no: 36, g: 3, t: "Aleksander Antosiak × Marianna Folga", url: "https://metryki.genealodzy.pl/index.php?op=pg&id=1483&sy=1926&kt=2&plik=036-037.jpg", r: "1 odczyt",
      q: "pomiędzy Aleksandrem Antosiakiem, kawalerem, gospodarzem, lat dwadzieścia trzy, synem Franciszka i Marcjanny z Lipków małżonków Antosiaków … i Marjanną Folgą, panną, lat dwadzieścia jeden, córką Józefa i Ludwiki z Siedleckich małżonków Folgów",
      tr: "19 września 1926 r., Chorzele — cztery dni przed śmiercią ojca pana młodego. Aleksander, 23 lata, z Połoni, i Marianna Folga, 21 lat, z Zagat. Umowę przedślubną zawarto u notariusza w Chorzelach 11 września." },
    { id: "z1839-185", osoby: ["anna-todor", "jozef-todor", "marianna-tod", "antoni-sniadach", "marianna-todorowna", "helena"], y: 1839, k: "zgon", no: 185, g: 6, t: "Anna Todorówna, 70 lat (Połoń)", scan: "4753d474963967d2b48a5b03e647996b52cd4d7fef02f640fea7fcdcff7358f8", r: "1 odczyt",
      q: "stawili się Antoni Śniadach Siestrzeniec zmarłej lat czterdzieści, tudzież Wojciech Antosiak sąsiad [?] zmarłej lat pięćdziesiąt … Umarła Anna Todorówna bezmężna, wyrobnica w Połoni mieszkająca lat siedemdziesiąt mająca, córka niegdy Józefa i Maryanny Małżonków Todorów urodzona we Wsi Połoni.",
      tr: "17 grudnia 1839 r. (5 XII st. st.) zgłoszono, że 16 grudnia o 9 rano zmarła w Połoni Anna Todorówna, niezamężna wyrobnica, ok. 70 lat (ur. ok. 1769), córka zmarłych Józefa i Marianny Todorów, urodzona w Połoni. Zgłosili: Antoni Śniadach, 40 l., jej siostrzeniec, i Wojciech Antosiak, 50 l., zapisany jako „sąsiad” [?] — pokrewieństwa przy nim akt nie podaje. Rodzina Todorów z Połoni; to Todorowie Heleny, żony Kacpra (prawdopodobne)." },
    { id: "s1842-22", osoby: ["adam-j-1820", "rozalia-k", "walenty"], y: 1842, k: "ślub", no: 22, g: 6, t: "Adam Jentosiak × Rozalia Bańkówna (Połoń)", scan: "f16af926a46f2a9de25154239767becba1b54a9e8b240bdf0cafe314f6136823", r: "1 odczyt",
      q: "w przytomności świadków Walentego Antosiaka Wuja zaślubionego lat czterdzieści … między Adamem Jentosiakiem młodzianem urodzonym w Połoni z Rozalii Jentosiakówny, lat dwadzieścia jeden mającym, i tamże przy Matce mieszkającym - a panną Rozalią Bańkówną, córką Bartłomieja i Katarzyny z Mierzejewskich Małżonków Bańków",
      tr: "6 lutego 1842 r. (25 I st. st.), Chorzele. Ślub Adama Jentosiaka, kawalera, 21 l. (ur. ok. 1820/21 w Połoni), syna Rozalii Jentosiakówny — bez ojca w akcie, więc nieślubnego — mieszkającego przy matce, z Rozalią Bańkówną, 23 l., córką Bartłomieja Bańki i Katarzyny z Mierzejewskich. Świadkowie: Walenty Antosiak, 40 l., „wuj” pana młodego, i Stanisław Sobol [?], 38 l. Matka pana młodego to najpewniej Rozalia, córka Kacpra i Heleny (ochrzczona 1796, żona Jana Bańki od 10.02.1821), a „wuj” Walenty — jej brat." },
    { id: "s1839-14", osoby: ["grzegorz-s", "marianna-k", "bartlomiej-s", "agnieszka-s", "adam-kuta", "elzbieta-kuta"], y: 1839, k: "ślub", no: 14, g: 5, t: "Grzegorz Sędrowski × Marianna Kuta (Połoń)", scan: "21d1a163c469c2637513bca5defbe91397ab0abd6750231144144ef393755a7c", r: "1 odczyt",
      q: "między Grzegorzem Sędrowskim młodzianem we Wsi Olszewce urodzonym z Bartłomieja Sędrowskiego i Agnieszki z Opałków [?] Małżonków synem lat dwadzieścia dwa mającym … a panną Maryanną Kucianką [?] córką Adama Kuty i Elżbiety z Bawdysów [?] Małżonków lat szesnaście skończonych mającą, i w Wsi Połoni przy rodzicach zostającą i urodzoną.",
      tr: "3 lutego 1839 r. (22 I st. st.), Chorzele. Ślub Grzegorza Sędrowskiego, 22 l. (ur. ok. 1816 w Olszewce), syna Bartłomieja i Agnieszki z Opałków [?], z Marianną Kutą, 16 l. (ur. ok. 1822 w Połoni), córką Adama Kuty i Elżbiety z Bawdysów [?]. Świadkowie: Jakub Sędrowski, 40 l., stryj pana młodego, i Marcin Kardaś, 48 l. Utożsamienie z rodzicami Rozalii (żony Feliksa) jest prawdopodobne — zgadzają się imiona, nazwiska, wieś i wiek (B 67/1848, B 64/1851)." },
    { id: "z1840-69", osoby: ["adam-kuta", "szymon-kuta", "ewa-kuta", "elzbieta-kuta", "marianna-k"], y: 1840, k: "zgon", no: 69, g: 6, t: "Adam Kuta, 50 lat (Połoń)", scan: "6e3110a50475c893559d625baa98f3607964131238c22ffcc0af12c836042e47", r: "1 odczyt",
      q: "stawili się Maciej Sofil [?] Zięć zmarłego lat dwadzieścia dziewięć, tudzież Szymon Kuta Brat zmarłego lat sześćdziesiąt … Umarł Adam Kuta wyrobnik w Połoni mieszkający lat pięćdziesiąt mający, syn niegdy Szymona Kuty i Ewy z Samsonów [?] Małżonków urodzony tamże, zostawiwszy po sobie owdowiałą żonę Elżbietę z Badysów [?].",
      tr: "10 kwietnia 1840 r. (29 III st. st.) zgłoszono, że 9 kwietnia zmarł w Połoni Adam Kuta, wyrobnik, ok. 50 l. (ur. ok. 1790 w Połoni), syn zmarłych Szymona Kuty i Ewy z Samsonów [?]; wdowa Elżbieta z Badysów [?]. Zgłosili zięć Maciej Sofil [?], 29 l., i brat Szymon Kuta, 60 l. „Badysów” to prawdopodobnie ta sama Elżbieta, co „z Bawdysów” w S 14/1839 — stąd Adam jest prawdopodobnie ojcem Marianny, żony Grzegorza Sędrowskiego." },
    { id: "s1843-49", osoby: ["aleksander-21", "rozalia-kuta", "wojciech-p", "marianna-grzyb", "adam-kuta", "elzbieta-kuta"], y: 1843, k: "ślub", no: 49, g: 5, t: "Aleksander Antosiak × Rozalia Kuta (Połoń)", scan: "5b2f189bc72954a1b59401abeaf26befa2596ea936827cff4638c62cb05a3ec8", r: "1 odczyt",
      q: "między Alexandrem Antosiakiem młodzianem we Wsi Połoni przy familii mieszkającym i urodzonym z niegdy Wojciecha i Maryanny z Grzybów Małżonków Antosiaków synem lat dwadzieścia dwa skończonych mającym - a panną Rozalią Kucianką [= Kutówną], córką niegdy Adama Kuty i żyjącej Elżbiety z Badydów Małżonków w Połoni przy Matce zostającą i urodzoną lat szesnaście skończonych mającą.",
      tr: "13 listopada 1843 r. (1 XI st. st.), Chorzele. Ślub Aleksandra Antosiaka, 22 l., syna zmarłych Wojciecha i Marianny z Grzybów, z Rozalią Kutą, 16 l., córką zmarłego Adama Kuty i żyjącej Elżbiety z Badydów [Bawdysów?]. Świadkowie: Wojciech (32 l.) i Karol (45 l.) Antosiakowie, nazwani „braćmi stryjecznymi” pana młodego. Rozalia i Marianna Sędrowska (matka Rozalii, żony Feliksa) miały tych samych rodziców — były siostrami; dlatego Aleksander był chrzestnym Rozalii w 1843 r." },
    { id: "z1845-47", osoby: ["antoni-sniadach", "lukasz-sniadoch", "marianna-todorowna"], y: 1845, k: "zgon", no: 47, g: 6, t: "Antoni Śniadach (Połoń)", scan: "8c55f56c991071b3c88f962d17bc5c57c6d1f5f642edcf1a33830606798bf57f", r: "1 odczyt",
      q: "stawili się Ignacy Śniadach syn zmarłego lat dwadzieścia trzy, tudzież Wojciech Opalach sąsiad zmarłego lat czterdzieści ośm … umarł Antoni Śniadach w Połoni przy Synie mieszkający lat [pięć?]dziesiąt mający, syn niegdy Łukasza i Maryanny Małżonków Śniadachów, urodzony tamże, zostawiwszy po sobie owdowiałą żonę Małgorzatę z Berkowskich.",
      tr: "12 czerwca 1845 r. (31 V st. st.) zgłoszono, że 11 czerwca zmarł w Połoni Antoni Śniadach, ok. 50 l. (pierwsza cyfra wieku zatarta), syn zmarłych Łukasza i Marianny Śniadachów, urodzony w Połoni; wdowa Małgorzata z Berkowskich. Zgłosili syn Ignacy, 23 l., i sąsiad Wojciech Opalach, 48 l. To siostrzeniec Anny Todorówny (Z 185/1839): jego matka Marianna, z domu Todorówna (ślub z Łukaszem w 1787 r.), była siostrą Anny. Księga nadpalona." },
    { id: "z1864-96", osoby: ["adam-ww", "wawrzyniec-w2", "katarzyna-l"], y: 1864, k: "zgon", no: 96, g: null, t: "Adam Antosiak, 12 lat (Łaz)", scan: "4ceeb7ae1072166b5edd436ad0908514921fcde6fe5f9de278b5df6c3688a8f0", r: "1 odczyt",
      q: "umarł w Łazie Adam Antosiak, syn niegdy Wawrzyńca i żyjącej Katarzyny z Żołowskich Małżonków Antosiaków rolników … lat dwanaście żyjący.",
      tr: "7 października 1864 r. zmarł w Łazie Adam Antosiak, 12 l., syn zmarłego Wawrzyńca i żyjącej Katarzyny z Żołowskich. Zgłosili Józef Więcek i Maciej Kowalewski, rolnicy z Łazu. To Adam, wnuk Walentego (ur. ok. 1852/53, U 73/1853); jego ojciec Wawrzyniec, brat Feliksa, zmarł w 1856 r." },
    { id: "u1865-132", osoby: ["adam-sw", "stanislaw-w", "marianna-b"], y: 1865, k: "chrzest", no: 132, g: null, t: "Adam, syn Stanisława i Marianny z Bączków (Połoń)", scan: "02df5effd764fb122267b473cc8dab622ec3b9adf39adf09e7a9e80e080035e6", r: "1 odczyt",
      q: "Stawił się Stanisław Antosiak rolnik z Połoni lat dwadzieścia siedm liczący … dziecię płci męzkiej urodzone tamże dnia dzisiejszego o godzinie trzeciej rano z Jego Małżonki Maryanny z Bączków lat dwadzieścia trzy liczącej. … nadane zostało imię Adam, a Rodzicami jego Chrzestnymi byli wyżej wspomniany Jan Antosiak i Ewa Bańka.",
      tr: "8 maja 1865 r., Połoń. Urodził się Adam, syn Stanisława Antosiaka, 27 l., i Marianny z Bączków, 23 l. Świadkowie: Jan Antosiak (41 [?]) i Jakub Bańka, 40 l.; chrzestni: Jan Antosiak i Ewa Bańka. Wiek i żona zgadzają się ze Stanisławem, synem Walentego (ślub 1862). Chrzestni to prawdopodobnie jego rodzeństwo: Jan (ur. 1834) i Ewa z Antosiaków Bańkowa." },
    { id: "z1839-137", osoby: ["marianna-st", "stanislaw-k", "helena-zyr"], y: 1839, k: "zgon", no: 137, g: 6, t: "Maryanna, córka Stanisława, 1 rok (Połoń)", scan: "3c66f0d4db758081415e6d6d38bcdf02cf184cf4b6023fdc844dff8b05049242", r: "1 odczyt",
      q: "stawili się Stanisław Antosiak ojciec zmarłej lat trzydzieści cztery, tudzież Szymon Mierzejewski lat trzydzieści liczący obydway rolnicy z Wsi Połoni … Umarła Maryanna Antosiakówna Rok jeden mająca, córka oświadczającego Stanisława Antosiaka i Heleny z Żyrów Małżonków w Połoni mieszkających.",
      tr: "8 sierpnia 1839 r. (27 VII st. st.) zgłoszono, że 7 sierpnia zmarła w Połoni Marianna, roczna córka Stanisława Antosiaka, 34 l., i Heleny z Żyrów. To dziecko ochrzczone w 1838 r. (akt 156/1838). Zgłosili ojciec i Szymon Mierzejewski, 30 l." },
];
